// src/context/UserContext.js
import React, { createContext, useState, useEffect } from 'react';
import {jwtDecode} from 'jwt-decode'; // ✅ default export

export const UserContext = createContext();

export const UserProvider = ({ children }) => {
    const [user, setUser] = useState(null);

    // Hàm đọc token từ localStorage
    const loadUserFromToken = () => {
        const token = localStorage.getItem('token');
        if (token) {
            try {
                const decoded = jwtDecode(token);

                // Set user object
                const currentUser = {
                    userId: decoded.sub || decoded.userId || null,
                    role: decoded.role || 'user',
                    name: decoded.name || decoded.given_name || decoded.email?.split('@')[0] || 'Unknown',
                    subscription: decoded.subscription || null,
                };

                setUser(currentUser);

                // Đồng bộ với localStorage (nếu component khác dùng)
                localStorage.setItem('userInfo', JSON.stringify(currentUser));

            } catch (err) {
                console.error('Invalid token:', err);
                logout();
            }
        }
    };

    useEffect(() => {
        loadUserFromToken();
    }, []);

    // Logout function
    const logout = () => {
        localStorage.removeItem('token');
        localStorage.removeItem('userInfo');
        setUser(null);
    };

    // Login function (nếu cần set trực tiếp từ API login)
    const login = (token) => {
        localStorage.setItem('token', token);
        loadUserFromToken();
    };

    return (
        <UserContext.Provider value={{ user, setUser, login, logout }}>
            {children}
        </UserContext.Provider>
    );
};
